import { useState, useMemo, useEffect } from 'react';
import { loadBulkIds, saveBulkIds, loadOrders, saveOrders, clearAllData } from './storage';

const TABS = ['Dashboard', 'Stock Manager', 'New Order', 'Order History'];

// ── HELPERS ──
const fmtNum = (n) => Number(n).toLocaleString('en-IN');
const fmtK   = (n) => { if (!n && n!==0) return '0'; if (n>=1000) return ((n/1000)%1===0?n/1000:(n/1000).toFixed(1))+'K'; return String(n); };
const fmtRs  = (n) => `₹${Number(n).toFixed(2)}`;
const popToRs = (pop) => pop / 1000; // 1K pop = ₹1

const parseQty = (val) => {
  const s = String(val).trim().toLowerCase().replace(/,/g,'');
  if (!s) return 0;
  if (s.endsWith('k'))    return Math.round(parseFloat(s)*1000);
  if (s.endsWith('l'))    return Math.round(parseFloat(s)*100000);
  return Math.round(parseFloat(s))||0;
};

const stockColor = (used, total) => {
  if (!total) return '#4a5278';
  const p = used/total;
  if (p>=0.9) return '#ff4d4d';
  if (p>=0.6) return '#ffaa00';
  return '#00e5a0';
};

// ── SMART ITEM-BASED ORDER SPLITTER ──
// Each ID has N items of X pop each. Orders must be split in WHOLE ITEMS only.
// Returns plan of { id, itemsSent, popSent } and total pop that will be sent
const planOrder = (bulkIds, targetPop) => {
  if (!targetPop || targetPop <= 0) return { plan:[], totalPop:0, totalItems:0, fulfilled:false, shortfall:0 };

  let remaining = targetPop;
  const plan = [];

  // Sort by available items descending
  const sorted = [...bulkIds]
    .map(b => {
      const itemSize   = b.itemSize || 1500;
      const itemsPerID = b.itemsPerID || 10;
      const usedItems  = b.usedItems || 0;
      const totalItems = itemsPerID; // each ID always has itemsPerID items max
      const availItems = Math.max(0, totalItems - usedItems);
      const availPop   = availItems * itemSize;
      return { ...b, itemSize, itemsPerID, usedItems, availItems, availPop };
    })
    .filter(b => b.availItems > 0)
    .sort((a,b) => b.availItems - a.availItems);

  for (const b of sorted) {
    if (remaining <= 0) break;
    // How many whole items needed from this ID?
    const itemsNeeded = Math.ceil(remaining / b.itemSize);
    const itemsToSend = Math.min(itemsNeeded, b.availItems);
    const popSent     = itemsToSend * b.itemSize;
    plan.push({
      id: b.id,
      itemSize: b.itemSize,
      itemsSent: itemsToSend,
      totalItems: b.itemsPerID,
      availItems: b.availItems,
      popSent,
      fullID: itemsToSend === b.availItems,
    });
    remaining -= popSent;
  }

  const totalPop   = plan.reduce((a,p)=>a+p.popSent,0);
  const totalItems = plan.reduce((a,p)=>a+p.itemsSent,0);
  const fulfilled  = remaining <= 0;
  return { plan, totalPop, totalItems, fulfilled, shortfall: Math.max(0,remaining) };
};

