    const entries=[], dupes=[];
    for (let i=fromN;i<=toN;i++) {
      const id=`${prefix}${i}`;
      if (bulkIds.find(b=>b.id===id)) dupes.push(id);
      else entries.push({id, label:id, itemSize:isz, itemsPerID:ipc, totalStock, usedStock:0, usedItems:0});
    }
    if (!entries.length) { notify('All IDs already exist.','error'); return; }
    setBulkIds(prev=>[...prev,...entries]);
    setRangeForm({prefix:'',from:'',to:'',itemSize:'1500',itemsPerID:'10'});
    setShowAdd(false);
    const count = entries.length;
    notify(`✓ ${count} IDs added · ${fmtNum(isz)} pop × ${ipc} items = ${fmtK(totalStock)} each · ${fmtK(totalStock*count)} total`);
  };

  const handleUpdateBulk = () => {
    const isz=parseInt(editBulk.itemSize), ipc=parseInt(editBulk.itemsPerID);
    setBulkIds(prev=>prev.map(b=>b.id===editBulk.id?{
      ...b, label:editBulk.label, itemSize:isz, itemsPerID:ipc, totalStock:isz*ipc
